package br.com.orientec.backend.adapter.out.persistence.entity.os; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; @Entity @Table(name="ordem_servico_peca") public class OrdemServicoPeca { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id") private Long id; @Column(name="ordem_servico_id") private Long ordemServicoId; @Column(name="sequencia") private Integer sequencia; @Column(name="item_id") private Integer itemId; @Column(name="pedido_id") private Integer pedidoId; @Column(name="descricao_snapshot") private String descricaoSnapshot; @Column(name="fornecedor_id") private Integer fornecedorId; @Column(name="preco_unitario") private java.math.BigDecimal precoUnitario; @Column(name="preco_venda") private java.math.BigDecimal precoVenda; @Column(name="quantidade") private java.math.BigDecimal quantidade; @Column(name="total") private java.math.BigDecimal total; public OrdemServicoPeca(){}  public Long getId(){return id;} public void setId(Long v){this.id=v;} public Long getOrdemServicoId(){return ordemServicoId;} public void setOrdemServicoId(Long v){this.ordemServicoId=v;} public Integer getSequencia(){return sequencia;} public void setSequencia(Integer v){this.sequencia=v;} public Integer getItemId(){return itemId;} public void setItemId(Integer v){this.itemId=v;} public Integer getPedidoId(){return pedidoId;} public void setPedidoId(Integer v){this.pedidoId=v;} public String getDescricaoSnapshot(){return descricaoSnapshot;} public void setDescricaoSnapshot(String v){this.descricaoSnapshot=v;} public Integer getFornecedorId(){return fornecedorId;} public void setFornecedorId(Integer v){this.fornecedorId=v;} public java.math.BigDecimal getPrecoUnitario(){return precoUnitario;} public void setPrecoUnitario(java.math.BigDecimal v){this.precoUnitario=v;} public java.math.BigDecimal getPrecoVenda(){return precoVenda;} public void setPrecoVenda(java.math.BigDecimal v){this.precoVenda=v;} public java.math.BigDecimal getQuantidade(){return quantidade;} public void setQuantidade(java.math.BigDecimal v){this.quantidade=v;} public java.math.BigDecimal getTotal(){return total;} public void setTotal(java.math.BigDecimal v){this.total=v;} }
